function setItem(t){state.item=t;$('#itembox').classList.toggle('item-empty',!t);$('#itemIcon').textContent=t?t.icon:'?';$('#itemName').textContent=t?t.name:'NO ITEM';$('#itembox .item-hint').textContent=t?'PRESS E TO USE':'DRIVE THROUGH A PICKUP';announce(t?`${t.icon} ${t.name} ACQUIRED`:'')}
function setStatus(text){$('#status').textContent=text}
function resetPositions(){player.position.set((Math.random()-.5)*8,0,20);state.yaw=Math.PI+(Math.random()-.5)*.24;player.rotation.y=state.yaw;state.speed=0;rival.position.set((Math.random()-.5)*8,0,-18);rival.rotation.y=0;ball.position.set((Math.random()-.5)*2,2,0);ball.userData.vel=new THREE.Vector3((Math.random()-.5)*2,1.3,(Math.random()-.5)*5);state.goalFreeze=2.2}
ball.userData.vel=new THREE.Vector3(0,0,0);resetPositions();
function goal(team){if(state.goalFreeze>0||!state.running)return;state[team]++;$('#blueScore').textContent=state.blue;$('#redScore').textContent=state.red;setStatus(team==='blue'?'BLUE CREW SCORES!':'RED RIOT SCORES!');announce(team==='blue'?'GOOOOAL! BLUE CREW':'RED RIOT SCORED!');resetPositions()}
function useItem(){if(!state.running||!state.item)return;const t=state.item;state.item=null;setItem(null);if(t.name==='TURBO BOOST'){state.boost=Math.min(100,state.boost+55);state.speed=Math.max(state.speed,23);announce('TURBO CHARGED!')}
else if(t.name==='BALL BLASTER'){const p=player.position.clone().add(new THREE.Vector3(Math.sin(state.yaw)*3,1,Math.cos(state.yaw)*3));const aim=ball.position.clone().sub(p).normalize();projectiles.push({mesh:sphere(scene,.34,mat(0xffc64d,.2,.3),p.x,p.y,p.z,12),vel:aim.multiplyScalar(24)});announce('BALL BLASTER!')}
else{const p=player.position.clone().add(new THREE.Vector3(-Math.sin(state.yaw)*2,.1,-Math.cos(state.yaw)*2));const peel=new THREE.Group();const shell=sphere(peel,.55,mat(0xffe055,.35),0,.3,0,14);shell.scale.set(1,.48,1);const stem=box(peel,.12,.3,.12,mat(0x5bc85e),0,.7,0);peel.position.copy(p);scene.add(peel);bananas.push({mesh:peel,life:14});announce('BANANA DEPLOYED!') }}
function spawnPickupAtRandom(p){p.mesh.position.set((Math.random()-.5)*24,.35,(Math.random()-.5)*48);p.mesh.visible=true;p.active=true}
const clock=new THREE.Clock();const camTarget=new THREE.Vector3();
function update(dt){if(!state.running)return;state.time-=dt;if(state.time<=0){state.time=0;endGame();return}state.cooldown=Math.max(0,state.cooldown-dt);state.goalFreeze=Math.max(0,state.goalFreeze-dt);if(state.toastTimer>0&&(state.toastTimer-=dt)<=0)$('#toast').classList.remove('show');
// User car: momentum, steering, handbrake drift and turbo
const h=state.held,forward=(h.w||h.arrowup?1:0)-(h.s||h.arrowdown?1:0),steer=(h.d||h.arrowright?1:0)-(h.a||h.arrowleft?1:0),brake=h.shift;
const boosting=(h[' ']||h.space)&&state.boost>0&&forward>=0;state.boost=Math.max(0,Math.min(100,state.boost+(boosting?-32:11)*dt));
const accel=boosting?37:21;state.speed+=forward*accel*dt;state.speed*=Math.pow(brake?.978:.93,dt*60);state.speed=THREE.MathUtils.clamp(state.speed,-8,boosting?31:21);
state.yaw-=steer*dt*(1.55+Math.abs(state.speed)*.035)*(brake?1.55:1)*(state.speed< -1?-1:1);player.rotation.y=state.yaw;player.position.x+=Math.sin(state.yaw)*state.speed*dt;player.position.z+=Math.cos(state.yaw)*state.speed*dt;player.position.x=THREE.MathUtils.clamp(player.position.x,-18.7,18.7);player.position.z=THREE.MathUtils.clamp(player.position.z,-29,29);player.userData.flame.visible=boosting;player.userData.flame.scale.setScalar(.8+Math.random()*.5);state.drift=brake&&Math.abs(steer)>0?Math.min(1,state.drift+dt*2):Math.max(0,state.drift-dt);
// Rival bot chases and challenges the ball
const rivalDir=new THREE.Vector3(ball.position.x-rival.position.x,0,ball.position.z-rival.position.z);const distR=rivalDir.length();if(distR>.1){rivalDir.normalize();const targetYaw=Math.atan2(rivalDir.x,rivalDir.z);let delta=Math.atan2(Math.sin(targetYaw-rival.rotation.y),Math.cos(targetYaw-rival.rotation.y));rival.rotation.y+=THREE.MathUtils.clamp(delta,-dt*2.6,dt*2.6);const botSpeed=distR<3?2:11;rival.position.x+=Math.sin(rival.rotation.y)*botSpeed*dt;rival.position.z+=Math.cos(rival.rotation.y)*botSpeed*dt;rival.position.x=THREE.MathUtils.clamp(rival.position.x,-18,18);rival.position.z=THREE.MathUtils.clamp(rival.position.z,-28,28)}
// Ball gravity, turf bounce and rolling drag
const v=ball.userData.vel;v.y-=17*dt;ball.position.addScaledVector(v,dt);if(ball.position.y<1.65){ball.position.y=1.65;if(v.y< -1)v.y=-v.y*.58;else v.y=0;v.x*=Math.pow(.985,dt*60);v.z*=Math.pow(.985,dt*60)}
if(Math.abs(ball.position.x)>19.2){ball.position.x=Math.sign(ball.position.x)*19.2;v.x*=-.72}if(Math.abs(ball.position.z)>30.4){ball.position.z=Math.sign(ball.position.z)*30.4;v.z*=-.72}
ball.rotation.x+=v.z*dt*.36;ball.rotation.z-=v.x*dt*.36;
