function bump(car,yaw,boost=0){const dx=ball.position.x-car.position.x,dz=ball.position.z-car.position.z,d=Math.hypot(dx,dz);if(d<2.8&&ball.position.y<4.2&&state.goalFreeze<=0){const nx=d>.01?dx/d:Math.sin(yaw),nz=d>.01?dz/d:Math.cos(yaw);const kick=car===player?Math.max(8,Math.abs(state.speed)*.95)+boost:10;v.x=nx*kick+Math.sin(yaw)*kick*.36;v.z=nz*kick+Math.cos(yaw)*kick*.36;v.y=Math.max(v.y,5.2+Math.min(kick*.09,2));if(car===player)announce('NICE SHOT!')}}bump(player,state.yaw,boosting?9:0);bump(rival,rival.rotation.y);
