// Smooth chase camera, slightly pulled back at speed
const behind=new THREE.Vector3(-Math.sin(state.yaw),0,-Math.cos(state.yaw));camTarget.set(player.position.x+behind.x*(10+Math.abs(state.speed)*.13),5.6+Math.abs(state.speed)*.045,player.position.z+behind.z*(10+Math.abs(state.speed)*.13));camera.position.lerp(camTarget,1-Math.pow(.001,dt));const look=new THREE.Vector3(player.position.x,1.2,player.position.z+Math.cos(state.yaw)*8);camera.lookAt(look);
$('#speed').textContent=String(Math.round(Math.abs(state.speed)*4.3)).padStart(3,'0');$('#boostText').textContent=Math.round(state.boost);$('#boostFill').style.width=`${state.boost}%`;
$('#clock').textContent=`${Math.floor(state.time/60)}:${String(Math.ceil(state.time%60)).padStart(2,'0')}`;
