$('#speed').textContent=String(Math.round(Math.abs(state.speed)*4.3)).padStart(3,'0');$('#boostText').textContent=Math.round(state.boost);$('#boostFill').style.width=`${state.boost}%`;$('#clock').textContent=`${Math.floor(state.time/60)}:${String(Math.ceil(state.time%60)).padStart(2,'0')}`;
