function startGame(){state.time=90;state.blue=0;state.red=0;state.boost=100;state.ended=false;state.running=true;state.item=null;$('#blueScore').textContent='0';$('#redScore').textContent='0';$('#clock').textContent='1:30';$('#status').textContent='KICK OFF';$('#play').textContent='START YOUR ENGINES';$('#footnote').textContent='WASD to drive · Space to boost · E to fire · Works on touch';$('#overlay').classList.add('hidden');setItem(null);resetPositions();state.goalFreeze=.8;camera.position.set(0,12,34);camera.lookAt(0,0,0)}
$('#play').addEventListener('click',startGame);
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();state.held[key]=true;if(key==='e')useItem();if(key==='enter'&&!state.running)startGame()});
