window.addEventListener('blur',()=>{state.held={}});
document.querySelectorAll('.mobile button').forEach(button=>{const key=button.dataset.key;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);state.held[key]=true;if(key==='e')useItem()});const release=e=>{e.preventDefault();state.held[key]=false};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release)});
